-- ==========================================================
-- upgrade_existing_db.sql : add the newer objects to a database that is already running.
-- GENERATED by build_install.py from the single files. Do not edit by hand.
--
-- Run it once as the owner account (avnadmin on Aiven), as one script.
-- It only ADDS one function and two procedures and grants EXECUTE on them.
-- No table, no data and no existing procedure is changed.
--   fn_standing_left     standing tickets left, shown on the event page
--   pc_update_customer   lets a customer edit the profile and change the password
--   pc_update_event      lets a super admin edit an event
-- Until this script has run, the web app still works; those three features are just switched off.
-- ==========================================================

-- ==========================================================
-- myv_myTickets/function/fn_standing_left.sql
-- ==========================================================
USE myv_myTickets;

DROP FUNCTION IF EXISTS fn_standing_left;

DELIMITER $$

-- How many STANDING tickets of an event can still be sold:
-- standing_capacity minus the standing tickets that already exist (paid or pending).
-- The counterpart of fn_available_seats, which only counts numbered seats.
-- Returns 0 when the event has no standing area, NULL when the event does not exist.
--
-- Usage:
--   SELECT fn_standing_left('EV01');
--   SELECT event_id, event_name, fn_standing_left(event_id) AS standing_left FROM event;
CREATE FUNCTION fn_standing_left(
  p_event_id VARCHAR(20)
)
RETURNS INT
READS SQL DATA
BEGIN
  DECLARE v_capacity INT;
  DECLARE v_used     INT;

  SELECT standing_capacity INTO v_capacity FROM event WHERE event_id = p_event_id;
  IF v_capacity IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COUNT(*) INTO v_used
    FROM ticket t
    JOIN seat s ON s.seat_id = t.seat_id
   WHERE t.event_id  = p_event_id
     AND s.seat_zone = 'STANDING';

  RETURN GREATEST(v_capacity - v_used, 0);
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets/procedure/pc_update_customer.sql
-- ==========================================================
USE myv_myTickets;

DROP PROCEDURE IF EXISTS pc_update_customer;

DELIMITER $$

-- Change the profile of a customer: name, email, phone number and (optionally) the password.
-- The customer_app account has no UPDATE right on the customer table, so this procedure is
-- the only way the web app can change a profile.
--   p_password  the NEW password hash, or NULL to keep the current password.
--               The web app checks the current password before it calls this procedure.
--   p_phone_num NULL or '' removes the phone number.
-- customer_id and username never change. A duplicate email is rejected by uq_customer_email.
CREATE PROCEDURE pc_update_customer(
  IN p_customer_id VARCHAR(20),
  IN p_name        VARCHAR(100),
  IN p_email       VARCHAR(100),
  IN p_phone_num   VARCHAR(20),
  IN p_password    VARCHAR(255)
)
BEGIN
  IF NOT EXISTS (SELECT 1 FROM customer WHERE customer_id = p_customer_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Customer not found';
  END IF;
  IF p_name IS NULL OR TRIM(p_name) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Full name is required';
  END IF;
  IF p_email IS NULL OR p_email NOT LIKE '_%@_%' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A valid email address is required';
  END IF;
  IF p_password IS NOT NULL AND p_password = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'The password cannot be empty';
  END IF;

  UPDATE customer
     SET name      = TRIM(p_name),
         email     = TRIM(p_email),
         phone_num = NULLIF(TRIM(COALESCE(p_phone_num, '')), ''),
         password  = COALESCE(p_password, password)
   WHERE customer_id = p_customer_id;
END$$

DELIMITER ;

-- ==========================================================
-- myv_myTickets_admin/procedure/pc_update_event.sql
-- ==========================================================
USE myv_myTickets_admin;

USE myv_myTickets_admin;

DROP PROCEDURE IF EXISTS pc_update_event;

DELIMITER $$

-- Edit an event of the MAIN database and write it to audit_log. Only a super_admin may do this.
--   p_admin_id          the admin who performs the action (must exist and be a super_admin)
--   p_event_id          the event to edit
--   p_standing_capacity 0 (or NULL) means the event has no standing area
-- What can change: name, artist, sale time, start time and standing capacity.
-- What cannot change: the venue (the seats of sold tickets belong to it) and the event_id.
-- Rules:
--   * an event that has already started is history and cannot be edited
--   * standing capacity cannot go below the standing tickets that already exist (paid or pending)
--   * sale_time < start_time and capacity >= 0 come from trg_event_bu_chk in the main database
-- Event and audit_log row are saved together or not at all (transaction).
CREATE PROCEDURE pc_update_event(
  IN p_admin_id          VARCHAR(20),
  IN p_event_id          VARCHAR(20),
  IN p_event_name        VARCHAR(150),
  IN p_artist            VARCHAR(150),
  IN p_sale_time         DATETIME,
  IN p_start_time        DATETIME,
  IN p_standing_capacity INT
)
BEGIN
  DECLARE v_level    VARCHAR(20);
  DECLARE v_start    DATETIME;
  DECLARE v_standing INT;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SELECT `level` INTO v_level FROM admin WHERE admin_id = p_admin_id;
  IF v_level IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Admin not found';
  END IF;
  IF v_level <> 'super_admin' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Only a super admin can edit events';
  END IF;

  IF p_event_name IS NULL OR TRIM(p_event_name) = '' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event name is required';
  END IF;
  IF p_sale_time IS NULL OR p_start_time IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sale time and start time are required';
  END IF;

  START TRANSACTION;

  -- Lock the event row while we check it
  SELECT start_time INTO v_start
    FROM myv_myTickets.event WHERE event_id = p_event_id FOR UPDATE;
  IF v_start IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event not found';
  END IF;
  IF v_start <= NOW() THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Event has already started and cannot be edited';
  END IF;

  SELECT COUNT(*) INTO v_standing
    FROM myv_myTickets.ticket t
    JOIN myv_myTickets.seat s ON s.seat_id = t.seat_id
   WHERE t.event_id = p_event_id AND s.seat_zone = 'STANDING';
  IF COALESCE(p_standing_capacity, 0) < v_standing THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Standing capacity cannot be lower than the standing tickets already booked';
  END IF;

  UPDATE myv_myTickets.event
     SET event_name        = TRIM(p_event_name),
         artist            = NULLIF(TRIM(COALESCE(p_artist, '')), ''),
         sale_time         = p_sale_time,
         start_time        = p_start_time,
         standing_capacity = COALESCE(p_standing_capacity, 0)
   WHERE event_id = p_event_id;

  INSERT INTO audit_log (admin_id, action, target_id)
  VALUES (p_admin_id, 'UPDATE_EVENT', p_event_id);

  COMMIT;
END$$

DELIMITER ;

-- ==========================================================
-- grants for the new objects
-- ==========================================================
GRANT EXECUTE ON FUNCTION  myv_myTickets.fn_standing_left   TO 'customer_app'@'%';
GRANT EXECUTE ON PROCEDURE myv_myTickets.pc_update_customer TO 'customer_app'@'%';
GRANT EXECUTE ON PROCEDURE myv_myTickets_admin.pc_update_event TO 'admin_app'@'%';
